848	        float line_len, string_id g_type, const std::vector<gradient::color_stop>& colors)
849	    {
850	        bool repeating = false;
851	        if(g_type == _linear_gradient_ || g_type == _radial_gradient_ || g_type == _conic_gradient_)
852	        {
853	            repeating = false;
854	        } else if(g_type == _repeating_linear_gradient_ || g_type == _repeating_radial_gradient_ ||
855	                  g_type == _repeating_conic_gradient_)
856	        {
857	            repeating = true;
858	        }
859	        int  none_units      = 0;
860	        bool has_transparent = false;
861	        for(const auto& item : colors)
862	        {
863	            if(item.is_color_hint)
864	            {
865	                if(!color_points.empty())
866	                {
867	                    color_points.back().hint =
868	                        item.length ? normalize_length(*item.length, line_len) : *item.angle / 360;
869	                }
870	                continue;
871	            }
872	            if(item.color.alpha == 0)
873	            {
874	                has_transparent = true;
875	            }
876	            if(item.length)
877	            {
878	                color_points.emplace_back(normalize_length(*item.length, line_len), item.color);
879	            } else if(item.angle)
880	            {
881	                color_points.emplace_back(*item.angle / 360, item.color);
882	            } else
883	            {
884	                if(!color_points.empty())
885	                {
886	                    none_units++;
887	                }
888	                color_points.emplace_back(0.0f, item.color);
889	            }
890	        }
891	        if(color_points.empty())
892	        {
893	            return false;
894	        }
895	
896	        if(!repeating)
897	        {
898	            // Add color point with offset 0 if not exists
899	            if(pixel_t(color_points[0].offset) != 0_px)
900	            {
901	                color_points.emplace(color_points.begin(), 0.0f, color_points[0].color);
902	            }
903	            // Add color point with offset 1.0 if not exists
904	            if(pixel_t(color_points.back().offset) < 1_px)
905	            {
906	                if(pixel_t(color_points.back().offset) == 0_px)
907	                {
908	                    color_points.back().offset = 1;
909	                    none_units--;
910	                } else
911	                {
912	                    color_points.emplace_back(1.0f, color_points.back().color);
913	                }
914	            }
915	        } else
916	        {
917	            // Add color point with offset 1.0 if not exists
918	            if(pixel_t(color_points.back().offset) == 0_px)
919	            {
920	                color_points.back().offset = 1;
921	                none_units--;
922	            }
923	        }
924	
925	        if(none_units > 0)
926	        {
927	            size_t i = 1;
928	            while(i < color_points.size())
929	            {
930	                if(pixel_t(color_points[i].offset) != 0_px)
931	                {
932	                    i++;
933	                    continue;
934	                }
935	                // Find next defined offset
936	                size_t j = i + 1;
937	                while(pixel_t(color_points[j].offset) == 0_px)
938	                {
939	                    j++;
940	                }
941	                size_t num    = j - i;
942	                float  sum    = color_points[i - 1].offset + color_points[j].offset;
943	                float  offset = sum / static_cast<float>(num + 1);
944	                while(i < j)
945	                {
946	                    color_points[i].offset = color_points[i - 1].offset + offset;
947	                    i++;
948	                }
949	            }
950	        }
951	
952	        // process transparent
953	        if(has_transparent)
954	        {
955	            color_points_transparent_fix();
956	        }
957	
958	        if(repeating)
959	        {
960	            repeat_color_points(color_points);
961	        }
962	
963	        return true;
964	    }
